/**
 * The 120 Then Malai parcels and their map colours, kept in a module that does not touch Leaflet, so pages that only need
 * parcel facts (field report, evidence, history, chat) never pull the map engine into the server render.
 * The data itself is generated by backend/scripts/export_frontend_data.py.
 */
import { VILLAGE_PARCELS, type VillageParcel } from "../data/villageParcels.generated";

export const THEN_MALAI_PARCELS: VillageParcel[] = VILLAGE_PARCELS;
export type ParcelId = string;

export const CROP_COLORS: Record<string, string> = {
  Rice: "#a3e635",
  Banana: "#facc15",
  Sugarcane: "#2dd4bf",
  Maize: "#c084fc",
  Coconut: "#fb7185",
  Groundnut: "#fb923c",
  Cotton: "#e2e8f0",
  Blackgram: "#38bdf8",
  Chilli: "#ef4444",
  Turmeric: "#eab308",
};
export const cropColor = (crop: string) => CROP_COLORS[crop] ?? "#ea580c";
export const HEALTH_COLORS: Record<string, string> = { normal: "#22c55e", watch: "#f59e0b", stress: "#ef4444", insufficient: "#64748b" };
export const healthColor = (status?: string) => HEALTH_COLORS[status ?? "insufficient"] ?? HEALTH_COLORS.insufficient;
